function validate([expression]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 60) return 'expression needs 1 to 60 characters.';
  if (!/^[a-z{},]+$/.test(expression)) return "Only '{', '}', ',' and lowercase letters are allowed.";
  // Each open brace tracks how many comma-separated parts it has and whether the current part is empty.
  const open = [];
  let empty = false;
  for (const ch of expression) {
    if (ch === '{') { open.push([1, empty]); empty = true; }
    else if (ch === ',') {
      if (!open.length) return 'A comma must be inside braces.';
      if (empty) return 'Every part between commas and braces needs at least one letter or group.';
      open[open.length - 1][0]++;
      empty = true;
    } else if (ch === '}') {
      if (!open.length) return 'The braces are not balanced.';
      if (empty) return 'Every part between commas and braces needs at least one letter or group.';
      const [parts] = open.pop();
      if (parts < 2) return 'Braces must hold at least two comma-separated expressions.';
      empty = false;
    } else empty = false;
  }
  if (open.length) return 'The braces are not balanced.';
  return null;
}

