        words.add(prefix + suffix);
      }
    }
    return words;
  };
  const stack = [];
  let union = new Set();
  let product = new Set(['']);
  for (const ch of expression) {
    if (ch === '{') {
      stack.push([union, product]);
      union = new Set();
      product = new Set(['']);
    } else if (ch === '}') {
      for (const word of product) union.add(word);
      const group = union;
      [union, product] = stack.pop();
      product = join(product, group);
    } else if (ch === ',') {
      for (const word of product) union.add(word);
      product = new Set(['']);
    } else {
      product = join(product, [ch]);
    }
  }
  for (const word of product) union.add(word);
  return [...union].sort();
}

