function braceExpansionII(expression) {
  // Recursive descent: split on top-level commas, otherwise multiply chunk by chunk.
  function evaluate(text) {
    const parts = [];
    let depth = 0, start = 0;
    for (let i = 0; i < text.length; i++) {
      if (text[i] === '{') depth++;
      else if (text[i] === '}') depth--;
      else if (text[i] === ',' && depth === 0) { parts.push(text.slice(start, i)); start = i + 1; }
    }
    parts.push(text.slice(start));
    if (parts.length > 1) return [...new Set(parts.flatMap(evaluate))];
    let result = [''];
    let i = 0;
    while (i < text.length) {
      let chunk;
      if (text[i] === '{') {
        let j = i, level = 0;
        do { if (text[j] === '{') level++; else if (text[j] === '}') level--; j++; } while (level > 0);
        chunk = evaluate(text.slice(i + 1, j - 1));
        i = j;
      } else { chunk = [text[i]]; i++; }
      result = result.flatMap(a => chunk.map(b => a + b));
    }
    return [...new Set(result)];
  }
  const words = evaluate(expression);
  words.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  return words;
}

