function generate(rand, size) {
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const [low, high, maxDepth, widest] = size === 'large' ? [35, 60, 3, 4] : [3, 20, 2, 3];
  function expr(depth) {
    const items = 1 + Math.floor(rand() * 3);
    let text = '';
    for (let i = 0; i < items; i++) {
      if (depth < maxDepth && rand() < (depth === 0 ? 0.7 : 0.45)) {
        const k = 2 + Math.floor(rand() * (widest - 1));
        const parts = [];
        for (let j = 0; j < k; j++) parts.push(expr(depth + 1));
        text += '{' + parts.join(',') + '}';
      } else text += pick();
    }
    return text;
  }
  for (;;) {
    const text = expr(0);
    if (text.length >= low && text.length <= high) return [text];
  }
}
